import java.util.*;
import java.io.*;

public class Main {
    static int[] searchAll(int[] a, int[] queries) {
        // Write your solution here
        return new int[0];
    }

    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int n = (int) in.nval;
        in.nextToken();
        int q = (int) in.nval;
        int[] a = new int[n], queries = new int[q];
        for (int i = 0; i < n; i++) {
            in.nextToken();
            a[i] = (int) in.nval;
        }
        for (int i = 0; i < q; i++) {
            in.nextToken();
            queries[i] = (int) in.nval;
        }
        int[] res = searchAll(a, queries);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < res.length; i++) sb.append(res[i]).append(i + 1 < res.length ? " " : "\n");
        System.out.print(sb);
    }
}
